LEVEL = 1
CFG = {1: 1.0, 2: 0.5, 3: 2.0}
budget, spend = CFG[LEVEL], [0.3, 0.3, 0.3, 0.3]
for i, s in enumerate(spend):
    if budget >= s:
        budget -= s; print("query %d: allowed, remaining %.1f" % (i + 1, budget))
    else:
        print("query %d: DENIED, budget exhausted" % (i + 1)); break

